                "INSERT INTO rail_plan_power_snapshot (plan_id, seq, section_id, substation_id,"
                        + " substation_key, limit_version, limit_kw, power_kw, start_utc, end_utc,"
                        + " created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
