                    ps.setInt(7, s.limitKw());
                    ps.setInt(8, s.powerKw());
                    ps.setLong(9, s.startUtc().toEpochMilli());
                    ps.setLong(10, s.endUtc().toEpochMilli());
                    ps.setLong(11, nowMillis);
                });
